# 方法 1：直接 PATCH
kubectl patch pod resize-demo --patch '{
  "spec": {
    "containers": [{
      "name": "app",
      "resources": {
        "requests": {"cpu": "200m", "memory": "256Mi"},
        "limits": {"cpu": "500m", "memory": "512Mi"}
      }
    }]
  }
}'

# 方法 2：编辑
kubectl edit pod resize-demo
